store = {1: {"order_id": 1, "customer_id": 3}, 2: {"order_id": 2, "customer_id": 5}}

def handle(store, method, path, body=None):
    parts = path.strip("/").split("/")
    if method == "POST" and parts == ["orders"]:
        if not body or "customer_id" not in body:
            return 422, {"error": "customer_id is required"}
        new_id = max(store) + 1
        store[new_id] = {"order_id": new_id, **body}
        return 201, store[new_id]
    key = int(parts[1])
    if key not in store:
        return 404, {"error": "not found"}
    if method == "GET":
        return 200, store[key]
    if method == "DELETE":
        del store[key]
        return 204, None
    return 405, {"error": "method not allowed"}

calls = [("GET", "/orders/1", None), ("GET", "/orders/9", None), ("POST", "/orders", {"customer_id": 8}),
         ("POST", "/orders", {"amount_cents": 5}), ("DELETE", "/orders/2", None), ("DELETE", "/orders/2", None)]
for method, path, body in calls:
    print(method, path, handle(store, method, path, body)[0])
print(sorted(store))
